Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
nfsd: don't set SVC_SOCK_ANONYMOUS when creating nfsd sockets

When creating nfsd sockets via the netlink interface, we do want to
register with the portmapper. Don't set SVC_SOCK_ANONYMOUS.

Reported-by: Steve Dickson <steved@redhat.com>
Fixes: 16a471177496 ("NFSD: add listener-{set,get} netlink command")
Cc: Lorenzo Bianconi <lorenzo@kernel.org>
Signed-off-by: Jeff Layton <jlayton@kernel.org>
Signed-off-by: Chuck Lever <chuck.lever@oracle.com>

Here is the root cause:
The bug was caused by setting the `SVC_SOCK_ANONYMOUS` flag when creating nfsd sockets via the netlink interface, which prevented these sockets from registering with the portmapper, leading to issues in their expected functionality.

Here is the patch:
  */
 int nfsd_nl_listener_set_doit(struct sk_buff *skb, struct genl_info *info)
 {
 	struct net *net = genl_info_net(info);
 	struct svc_xprt *xprt, *tmp;
 	const struct nlattr *attr;
 	struct svc_serv *serv;
 	LIST_HEAD(permsocks);
 	struct nfsd_net *nn;
 	int err, rem;

 	mutex_lock(&nfsd_mutex);

 	err = nfsd_create_serv(net);
 	if (err) {
 		mutex_unlock(&nfsd_mutex);
 		return err;
 	}

 	nn = net_generic(net, nfsd_net_id);
 	serv = nn->nfsd_serv;

 	spin_lock_bh(&serv->sv_lock);

 	/* Move all of the old listener sockets to a temp list */
 	list_splice_init(&serv->sv_permsocks, &permsocks);

 	/*
 	 * Walk the list of server_socks from userland and move any that match
 	 * back to sv_permsocks
 	 */
 	nlmsg_for_each_attr(attr, info->nlhdr, GENL_HDRLEN, rem) {
 		struct nlattr *tb[NFSD_A_SOCK_MAX + 1];
 		const char *xcl_name;
 		struct sockaddr *sa;

 		if (nla_type(attr) != NFSD_A_SERVER_SOCK_ADDR)
 			continue;

 		if (nla_parse_nested(tb, NFSD_A_SOCK_MAX, attr,
 				     nfsd_sock_nl_policy, info->extack) < 0)
 			continue;

 		if (!tb[NFSD_A_SOCK_ADDR] || !tb[NFSD_A_SOCK_TRANSPORT_NAME])
 			continue;

 		if (nla_len(tb[NFSD_A_SOCK_ADDR]) < sizeof(*sa))
 			continue;

 		xcl_name = nla_data(tb[NFSD_A_SOCK_TRANSPORT_NAME]);
 		sa = nla_data(tb[NFSD_A_SOCK_ADDR]);

 		/* Put back any matching sockets */
 		list_for_each_entry_safe(xprt, tmp, &permsocks, xpt_list) {
 			/* This shouldn't be possible */
 			if (WARN_ON_ONCE(xprt->xpt_net != net)) {
 				list_move(&xprt->xpt_list, &serv->sv_permsocks);
 				continue;
 			}

 			/* If everything matches, put it back */
 			if (!strcmp(xprt->xpt_class->xcl_name, xcl_name) &&
 			    rpc_cmp_addr_port(sa, (struct sockaddr *)&xprt->xpt_local)) {
 				list_move(&xprt->xpt_list, &serv->sv_permsocks);
 				break;
 			}
 		}
 	}

 	/* For now, no removing old sockets while server is running */
 	if (serv->sv_nrthreads && !list_empty(&permsocks)) {
 		list_splice_init(&permsocks, &serv->sv_permsocks);
 		spin_unlock_bh(&serv->sv_lock);
 		err = -EBUSY;
 		goto out_unlock_mtx;
 	}

 	/* Close the remaining sockets on the permsocks list */
 	while (!list_empty(&permsocks)) {
 		xprt = list_first_entry(&permsocks, struct svc_xprt, xpt_list);
 		list_move(&xprt->xpt_list, &serv->sv_permsocks);

 		/*
 		 * Newly-created sockets are born with the BUSY bit set. Clear
 		 * it if there are no threads, since nothing can pick it up
 		 * in that case.
 		 */
 		if (!serv->sv_nrthreads)
 			clear_bit(XPT_BUSY, &xprt->xpt_flags);

 		set_bit(XPT_CLOSE, &xprt->xpt_flags);
 		spin_unlock_bh(&serv->sv_lock);
 		svc_xprt_close(xprt);
 		spin_lock_bh(&serv->sv_lock);
 	}

 	spin_unlock_bh(&serv->sv_lock);

 	/* walk list of addrs again, open any that still don't exist */
 	nlmsg_for_each_attr(attr, info->nlhdr, GENL_HDRLEN, rem) {
 		struct nlattr *tb[NFSD_A_SOCK_MAX + 1];
 		const char *xcl_name;
 		struct sockaddr *sa;
 		int ret;

 		if (nla_type(attr) != NFSD_A_SERVER_SOCK_ADDR)
 			continue;

 		if (nla_parse_nested(tb, NFSD_A_SOCK_MAX, attr,
 				     nfsd_sock_nl_policy, info->extack) < 0)
 			continue;

 		if (!tb[NFSD_A_SOCK_ADDR] || !tb[NFSD_A_SOCK_TRANSPORT_NAME])
 			continue;

 		if (nla_len(tb[NFSD_A_SOCK_ADDR]) < sizeof(*sa))
 			continue;

 		xcl_name = nla_data(tb[NFSD_A_SOCK_TRANSPORT_NAME]);
 		sa = nla_data(tb[NFSD_A_SOCK_ADDR]);

 		xprt = svc_find_listener(serv, xcl_name, net, sa);
 		if (xprt) {
 			svc_xprt_put(xprt);
 			continue;
 		}

-		ret = svc_xprt_create_from_sa(serv, xcl_name, net, sa,
-					      SVC_SOCK_ANONYMOUS,
+		ret = svc_xprt_create_from_sa(serv, xcl_name, net, sa, 0,
 					      get_current_cred());
 		/* always save the latest error */
 		if (ret < 0)
 			err = ret;
 	}

 	if (!serv->sv_nrthreads && list_empty(&nn->nfsd_serv->sv_permsocks))
 		nfsd_destroy_serv(net);

 out_unlock_mtx:
 	mutex_unlock(&nfsd_mutex);

 	return err;
 }



